const path = require('path');
const ROOT = path.resolve('/srv/public');
function publicFile(name) {
  const candidate = path.resolve(ROOT, name);
  if (!candidate.startsWith(ROOT + path.sep)) throw new Error('outside public root');
  return candidate;
}
module.exports = { publicFile };

const serialize = require('node-serialize');
function importJob(req) { return serialize.unserialize(req.body.payload); }
module.exports = { importJob };

const { spawn } = require('child_process');
function resize(file) { return spawn('convert', [file, '-resize', '200x200', 'out.png'], { shell: false }); }
module.exports = { resize };

const users = require('../db/users');
module.exports = async function user(req, res) {
  if (req.user.id !== req.params.id) return res.sendStatus(403);
  return res.json(await users.byId(req.params.id));
};

